changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'webhook.dispatch.backoff-schedule', 'PT1M,PT5M,PT15M,PT1H,PT6H', 'STRING', 'Расписание задержек повторных попыток исходящего webhook (ISO-8601, через запятую). Число элементов определяет максимальное число попыток.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'webhook.dispatch.backoff-schedule');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'webhook.dispatch.batch-size', '50', 'NUMBER', 'Максимальное число исходящих webhook-задач, выбираемых планировщиком за один проход.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'webhook.dispatch.batch-size');
